import json
with open('transcript.jsonl') as f:
    for i,line in enumerate(f):
        try: o=json.loads(line)
        except Exception as e: print(i,'ERR',e); continue
        t=o.get('type')
        msg=o.get('message',{})
        c=msg.get('content') if isinstance(msg,dict) else None
        summary=[]
        if isinstance(c,list):
            for b in c:
                bt=b.get('type')
                if bt=='text': summary.append('TEXT:'+b['text'][:150].replace('\n',' '))
                elif bt=='tool_use': summary.append('TOOL:'+b.get('name','')+' '+json.dumps(b.get('input',{}))[:200])
                elif bt=='tool_result':
                    cc=b.get('content')
                    s=json.dumps(cc)[:150] if cc else ''
                    summary.append('RESULT:'+s)
                elif bt=='thinking': summary.append('THINK:'+b.get('thinking','')[:100].replace('\n',' '))
        elif isinstance(c,str): summary.append('STR:'+c[:150].replace('\n',' '))
        print(i,t,len(line),' | '.join(summary))
"

