  darkPlastic: std(0x1b1e22, 0.55), fanBlade: std(0x2b3035, 0.5, 0, { side: THREE.DoubleSide }), crossBlade: std(0xaeb7c0, 0.45, 0.1),
  comp: new THREE.MeshPhysicalMaterial({ color: 0x272c32, roughness: 0.38, metalness: 0.55, clearcoat: 0.7, clearcoatRoughness: 0.3 }),
  brass: std(0xc39b4c, 0.28, 1), copper: std(0xc4764a, 0.3, 1), rubber: std(0x151719, 0.9),
