  map: canvasTex(512, 512, (g, w, h) => {
    g.fillStyle = '#c9c0b3'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#8b7f70'; g.lineWidth = 10; g.strokeRect(24, 24, w - 48, h - 48);
