/* ---------- refrigerant circuit ---------- */
const rev = (a) => a.slice().reverse();
function buildCircuit(nodes) {
  const rp = roundPath(nodes, 0.035);
  const pts = rp.map((o) => o.p); const curve = new PolyCurve(pts); const cum = curve.cum; const n = pts.length;
  const runs = {}; let order = [];
  rp.forEach((o, i) => { if (o.coil) { if (!runs[o.coil]) { runs[o.coil] = [i, i]; order.push(o.coil); } else runs[o.coil][1] = i; } });
  const [cond, evap] = [runs[order[0]], runs[order[1]]];
  let exv = rp.findIndex((o, i) => o.exv && i > cond[1]); if (exv < 0) exv = cond[1] + 1;
  const T = new Float32Array(n), P = new Uint8Array(n);
  const f = (i, r) => (cum[i] - cum[r[0]]) / Math.max(1e-6, cum[r[1]] - cum[r[0]]);
  for (let i = 0; i < n; i++) {
    if (i < cond[0]) { T[i] = 1; P[i] = 0; }
    else if (i <= cond[1]) { const k = f(i, cond); T[i] = lerp(1, 0.56, k); P[i] = k < 0.25 ? 0 : k < 0.85 ? 2 : 1; }
    else if (i < exv) { T[i] = 0.56; P[i] = 1; }
    else if (i < evap[0]) { T[i] = 0.04; P[i] = 2; }
    else if (i <= evap[1]) { const k = f(i, evap); T[i] = lerp(0.04, 0.3, k); P[i] = k < 0.85 ? 2 : 0; }
    else { T[i] = 0.32; P[i] = 0; }
  }
  const K = Math.ceil(curve.len / 0.008); const lut = new Float32Array((K + 1) * 3), lT = new Float32Array(K + 1), lP = new Uint8Array(K + 1);
  let j = 0; const tmp = V();
  for (let k = 0; k <= K; k++) {
    const d = (k / K) * curve.len; while (j < n - 2 && cum[j + 1] < d) j++;
    const a = (d - cum[j]) / Math.max(1e-6, cum[j + 1] - cum[j]);
    tmp.copy(pts[j]).lerp(pts[j + 1], clamp(a, 0, 1)); lut.set([tmp.x, tmp.y, tmp.z], k * 3);
    lT[k] = lerp(T[j], T[j + 1], clamp(a, 0, 1)); lP[k] = a < 0.5 ? P[j] : P[j + 1];
