/* ---------- particles ---------- */
const pointVS = `attribute float aSize; attribute float aAlpha; attribute vec3 aColor; uniform float uScale; varying float vA; varying vec3 vC;
  void main(){ vec4 mv=modelViewMatrix*vec4(position,1.); gl_Position=projectionMatrix*mv; gl_PointSize=min(aSize*uScale/-mv.z,72.); vA=aAlpha; vC=aColor; }`;
const pointFS = `varying float vA; varying vec3 vC; void main(){ vec2 d=gl_PointCoord-.5; float r=length(d); float a=smoothstep(.5,.0,r); a*=a; if(a*vA<.004) discard; gl_FragColor=vec4(vC,a*vA); }`;
const pointMats = [];
function makePoints(n) {
  const geo = new THREE.BufferGeometry();
  const attrs = { pos: new Float32Array(n * 3), col: new Float32Array(n * 3), a: new Float32Array(n), s: new Float32Array(n) };
  geo.setAttribute('position', new THREE.BufferAttribute(attrs.pos, 3).setUsage(THREE.DynamicDrawUsage));
  geo.setAttribute('aColor', new THREE.BufferAttribute(attrs.col, 3).setUsage(THREE.DynamicDrawUsage));
  geo.setAttribute('aAlpha', new THREE.BufferAttribute(attrs.a, 1).setUsage(THREE.DynamicDrawUsage));
  geo.setAttribute('aSize', new THREE.BufferAttribute(attrs.s, 1).setUsage(THREE.DynamicDrawUsage));
  const mat = new THREE.ShaderMaterial({ uniforms: { uScale: { value: 800 } }, vertexShader: pointVS, fragmentShader: pointFS, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending });
  pointMats.push(mat);
  const pts = new THREE.Points(geo, mat); pts.frustumCulled = false; pts.renderOrder = 5; scene.add(pts);
  const flush = () => { for (const k of ['position', 'aColor', 'aAlpha', 'aSize']) geo.attributes[k].needsUpdate = true; };
  return { pts, ...attrs, flush };
}

// refrigerant beads
const MAXB = 560;
const beads = new THREE.InstancedMesh(new THREE.SphereGeometry(1, 12, 8), new THREE.MeshBasicMaterial({ toneMapped: false }), MAXB);
