  const c = circuit; if (!c) return; const K = c.K, L = c.lut;
  for (let i = 0; i < beadCount; i++) {
    let u = beadU[i]; const k = Math.min(K, Math.floor(u * K));
    u += (dt * 0.42 * PHASE_SPEED[c.lP[k]]) / c.len; u -= Math.floor(u); beadU[i] = u;
    const f = u * K, k0 = Math.min(K - 1, Math.floor(f)), k1 = k0 + 1, a = f - k0;
    const x = L[k0 * 3] + (L[k1 * 3] - L[k0 * 3]) * a, y = L[k0 * 3 + 1] + (L[k1 * 3 + 1] - L[k0 * 3 + 1]) * a, z = L[k0 * 3 + 2] + (L[k1 * 3 + 2] - L[k0 * 3 + 2]) * a;
