args.streamContent:
/* ---------- state ---------- */
const SYS = { split: buildSplit(), mono: buildMono() };
for (const s of Object.values(SYS)) s.streamsP = { cool: s.streams.cool.map(prepStream), heat: s.streams.heat.map(prepStream) };
const TEMPS = { cool: { start: 27, target: 22, out: 35, outSub: 'Summer afternoon' }, heat: { start: 16, target: 21, out: 3, outSub: 'Winter morning' } };
const tour = $('tour'), tagsEl = $('tags');
let tags = [];

function applyState() {
  const sys = SYS[S.system];
  for (const s of Object.values(SYS)) s.group.visible = s === sys;
  buildWall(sys.notches);
  setCircuit(sys.circuits[S.mode]);
  setStreams(sys.streamsP[S.mode]);
  sites = sys.sites; resetHeat();
  resetDrops(sys.drips[S.mode]);
  buildTags();
  document.body.dataset.mode = S.mode;
  document.querySelectorAll('[data-system]').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.system === S.system)));
  document.querySelectorAll('[data-mode]').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.mode === S.mode)));
  const sp = S.system === 'split', cool = S.mode === 'cool', T = TEMPS[S.mode];
  $('stSystem').textContent = sp ? 'Split system' : 'Monoblock';
  $('stMode').textContent = cool ? 'Cooling' : 'Heating';
  $('tOut').textContent = String(T.out); $('tOutSub').textContent = T.outSub; $('tInSub').textContent = `Target ${T.target} °C`;
  const oc = sp ? 'Outdoor coil' : 'Outdoor-air coil';
  $('absWhere').textContent = cool ? 'Indoor coil, from room air' : `${oc}, from ${T.out} °C outside air`;
  $('relWhere').textContent = cool ? `${oc}, into ${T.out} °C outside air` : 'Indoor coil, into room air';
  lastTIn = null; idleIdx = 0; idleT = 0;
  renderTour();
}

/* ---------- labels ---------- */
function buildTags() {
  tagsEl.innerHTML = ''; tags = [];
  const sys = SYS[S.system];
  for (const [key, a] of Object.entries(sys.anchors)) addTag(key, a);
  for (const site of ['indoor', 'outdoor']) {
    addTag('heat-' + site, {
      p: sys.heatTags[site], side: site === 'indoor' ? 'l' : 'r', heat: true,
      t: () => (roleOf(site) === 'abs' ? '↓ Heat absorbed' : '↑ Heat released'),
      s: () => (roleOf(site) === 'abs' ? (site === 'indoor' ? 'from room air' : 'from outdoor air') : (site === 'indoor' ? 'into room air' : 'to outdoor air')),
    });
  }
  for (const t of tags) { t.b.textContent = typeof t.a.t === 'function' ? t.a.t(S.mode) : t.a.t; t.s.textContent = t.a.s ? t.a.s(S.mode) : ''; }
}
function addTag(key, a) {
  const el = document.createElement('div');
  el.className = `tag ${a.side || 'r'}${a.heat ? ' heat' : ''}`;
  el.innerHTML = '<i class="d"></i><i class="ln"></i><div class="tx"><b></b><span></span></div>';
  tagsEl.appendChild(el);
  tags.push({ key, a, el, b: el.querySelector('b'), s: el.querySelector('span') });
}
const proj = V();
function updateTags() {
  tagsEl.style.display = S.labels ? '' : 'none'; if (!S.labels) return;
  const w = innerWidth, h = innerHeight; const hl = S.guide >= 0 ? steps()[S.guide].hl : [];
  for (const t of tags) {
    const p = typeof t.a.p === 'function' ? t.a.p(S.mode) : t.a.p;
    proj.copy(p).project(camera);
    const dist = camera.position.distanceTo(p);
    const isHl = hl.includes(t.key) || (t.a.heat && hl.includes('heat'));
    let vis = proj.z < 1 && Math.abs(proj.x) < 1.05 && Math.abs(proj.y) < 1.05;
    if (t.a.minor && !isHl && dist > 2.4) vis = false;
    if (!t.a.minor && !t.a.heat && !isHl && dist > 15) vis = false;
    t.el.style.opacity = vis ? '1' : '0';
    t.el.classList.toggle('hl', isHl);
    if (!vis) continue;
    const x = ((proj.x * 0.5 + 0.5) * w).toFixed(1), y = ((-proj.y * 0.5 + 0.5) * h).toFixed(1); const side = t.a.side || 'r';
    t.el.style.transform = side === 'l' ? `translate3d(${x}px,${y}px,0) translate(calc(-100% + 3.5px),-50%)`
      : side === 'u' ? `translate3d(${x}px,${y}px,0) translate(-50%,calc(-100% + 3.5px))` : `translate3d(${x}px,${y}px,0) translate(-3.5px,-50%)`;
  }
}

/* ---------- camera ---------- */
const HOME = { t: V(0.2, 1.2, -0.6), p: V(-0.9, 2.45, 7.5) };
let atHome = true, tween = null;
function homeView() {
  const k = clamp(1.62 / camera.aspect, 1, 2.3); const dir = HOME.p.clone().sub(HOME.t);
  const t = HOME.t.clone(); if (camera.aspect < 0.9) t.y -= 0.35;
  return { t, p: t.clone().addScaledVector(dir, k) };
}
function viewFor(f) {
  const v = SYS[S.system].views[f];
  if (!v) return homeView();
  const k = camera.aspect < 0.9 ? 1.7 : 1; return { t: v.t.clone(), p: v.t.clone().addScaledVector(v.o, k) };
}
function flyTo(v, dur = 1.6) {
  if (reduced || dur === 0) { camera.position.copy(v.p); controls.target.copy(v.t); tween = null; return; }
  tween = { p0: camera.position.clone(), t0: controls.target.clone(), p1: v.p.clone(), t1: v.t.clone(), s: performance.now(), d: dur * 1000 };
}
function updateTween(now) {
  if (!tween) return; const k = clamp((now - tween.s) / tween.d, 0, 1), e = ease(k);
  camera.position.lerpVectors(tween.p0, tween.p1, e); controls.target.lerpVectors(tween.t0, tween.t1, e);
  if (k < 1) camera.position.y += Math.sin(Math.PI * k) * 0.25 * tween.p0.distanceTo(tween.p1) * 0.08;
  if (k >= 1) tween = null;
}
controls.addEventListener('start', () => { tween = null; atHome = false; });
function zoom(f) {
  const d = camera.position.clone().sub(controls.target); const len = clamp(d.length() * f, controls.minDistance, controls.maxDistance);
  atHome = false; flyTo({ t: controls.target.clone(), p: controls.target.clone().addScaledVector(d.normalize(), len) }, 0.45);
}

/* ---------- guided explanation ---------- */
const STEP_DUR = 8.5;
function steps() {
  const sp = S.system === 'split', cool = S.mode === 'cool', ocn = sp ? 'outdoor coil' : 'outdoor-air coil';
  return [
    { f: 'overview', hl: ['iucoil', 'oucoil', 'heat'], x: () => `Air conditioning doesn't make cold. It <b>moves heat</b>, and right now it is carrying heat ${S.mode === 'cool' ? 'out of the room' : 'into the room'}.` },
    { f: cool ? 'indoor' : 'outdoor', hl: [cool ? 'iucoil' : 'oucoil', 'heat', 'drain'], x: () => (S.mode === 'cool'
      ? 'The indoor coil runs at about 7 °C. Warm room air crosses it and <b>gives up its heat</b> to the evaporating refrigerant. Moisture condenses into water.'
      : `The ${ocn} runs at about −4 °C, colder than the 3 °C outside air, so it still <b>absorbs heat</b> as the refrigerant evaporates.`) },
    { f: 'comp', hl: ['comp'], x: () => 'The compressor squeezes the cool, low-pressure vapor. Its <b>pressure and temperature jump</b>, to roughly 70 °C.' },
    { f: cool ? 'outdoor' : 'indoor', hl: [cool ? 'oucoil' : 'iucoil', 'heat'], x: () => (S.mode === 'cool'
      ? `At 48 °C the refrigerant is hotter than the 35 °C air, so the ${ocn} <b>releases the heat</b> outdoors and the refrigerant condenses to a liquid.`
      : 'The hot refrigerant condenses in the indoor coil at about 45 °C and <b>releases its heat</b> into the room air.') },
    { f: 'exv', hl: ['exv'], x: () => 'The expansion valve drops the pressure. Part of the liquid flashes to vapor and it turns <b>very cold</b>, ready to absorb heat again.' },
    { f: 'rv', hl: ['rv', 'iucoil', 'oucoil'], flip: true, x: () => `The reversing valve redirects the compressor's hot gas. It just switched to <b>${S.mode === 'cool' ? 'Cooling' : 'Heating'}</b>, so the two coils have swapped roles.` },
